package cn.adc.duration;
import cn.adc.shared.audit.AuditDocuments;import tools.jackson.databind.JsonNode;import java.sql.*;import java.util.*;
/** Writes are called only inside the shared command/catalog transaction. No delete API. */
public final class DurationRepository {
 public JsonNode version(Connection c,long id,int version)throws SQLException {try(var p=c.prepareStatement("SELECT row_to_json(t)::text FROM adc.project_duration_version t WHERE project_id=? AND duration_version_no=?")){p.setLong(1,id);p.setInt(2,version);try(var r=p.executeQuery()){return r.next()?AuditDocuments.parse(r.getString(1)):null;}}}
 public JsonNode current(Connection c,long id)throws SQLException {try(var p=c.prepareStatement("SELECT row_to_json(t)::text FROM adc.project_duration_version t WHERE project_id=? AND publication_status='CURRENT'")){p.setLong(1,id);try(var r=p.executeQuery()){return r.next()?AuditDocuments.parse(r.getString(1)):null;}}}
 public List<JsonNode> current(Connection c)throws SQLException {var out=new ArrayList<JsonNode>();try(var p=c.prepareStatement("SELECT row_to_json(t)::text FROM adc.project_duration_version t WHERE publication_status='CURRENT' ORDER BY project_id");var r=p.executeQuery()){while(r.next())out.add(AuditDocuments.parse(r.getString(1)));}return List.copyOf(out);}
 public List<JsonNode> currentPage(Connection c,int limit,long after)throws SQLException {var out=new ArrayList<JsonNode>();try(var p=c.prepareStatement("SELECT row_to_json(t)::text FROM adc.project_duration_version t WHERE publication_status='CURRENT' AND project_id>? ORDER BY project_id LIMIT ?")){p.setLong(1,after);p.setInt(2,limit+1);try(var r=p.executeQuery()){while(r.next())out.add(AuditDocuments.parse(r.getString(1)));}}return List.copyOf(out);}
 public long nextProject(Connection c)throws SQLException {try(var s=c.createStatement();var r=s.executeQuery("SELECT COALESCE(max(project_id),0) FROM adc.project_duration_version")){r.next();return Math.addExact(r.getLong(1),1);}}
 public int nextVersion(Connection c,long id)throws SQLException {try(var p=c.prepareStatement("SELECT COALESCE(max(duration_version_no),0) FROM adc.project_duration_version WHERE project_id=?")){p.setLong(1,id);try(var r=p.executeQuery()){r.next();return Math.addExact(r.getInt(1),1);}}}
 public void create(Connection c,long id,int version,String name,int minutes)throws SQLException {try(var p=c.prepareStatement("INSERT INTO adc.project_duration_version(project_id,duration_version_no,project_name,duration_minutes,publication_status) VALUES(?,?,?,?,'DRAFT')")){p.setLong(1,id);p.setInt(2,version);p.setString(3,name);p.setInt(4,minutes);p.executeUpdate();}}
 public void edit(Connection c,long id,int version,String name,int minutes)throws SQLException {try(var p=c.prepareStatement("UPDATE adc.project_duration_version SET project_name=?,duration_minutes=? WHERE project_id=? AND duration_version_no=? AND publication_status='DRAFT'")){p.setString(1,name);p.setInt(2,minutes);p.setLong(3,id);p.setInt(4,version);if(p.executeUpdate()!=1)throw new IllegalArgumentException("DRAFT_REQUIRED");}}
 public void supersede(Connection c,long id,int version)throws SQLException {try(var p=c.prepareStatement("UPDATE adc.project_duration_version SET publication_status='SUPERSEDED' WHERE project_id=? AND duration_version_no=? AND publication_status='CURRENT'")){p.setLong(1,id);p.setInt(2,version);if(p.executeUpdate()!=1)throw new IllegalArgumentException("CURRENT_CHANGED");}}
 public void publish(Connection c,long id,int version,java.time.Instant time,String actor,JsonNode evidence)throws SQLException {try(var p=c.prepareStatement("UPDATE adc.project_duration_version SET publication_status='CURRENT',published_at=?,published_by=?,publication_evidence=?::jsonb WHERE project_id=? AND duration_version_no=? AND publication_status='DRAFT'")){p.setObject(1,time.atOffset(java.time.ZoneOffset.UTC));p.setString(2,actor);p.setString(3,evidence.toString());p.setLong(4,id);p.setInt(5,version);if(p.executeUpdate()!=1)throw new IllegalArgumentException("DRAFT_REQUIRED");}}
}
